3	import { useDraggable } from '@dnd-kit/core'
4	import { CSS } from '@dnd-kit/utilities'
5	import { cn } from '@/lib/utils'
6	import type { CalendarBooking } from '@/components/calendar/CalendarView'
7	
8	interface DayChairCardProps {
9	  booking: CalendarBooking
10	  sourceArtistId: string
11	  isSelected?: boolean
12	  onClick?: (e: React.MouseEvent | React.KeyboardEvent) => void
13	  onResizeStart?: (e: React.PointerEvent) => void
14	}
15	
16	function getStatusPill(
17	  status: string,
18	  depositCents: number | null | undefined,
19	  depositPaid: boolean | null | undefined
20	): 'LIVE' | 'PAID' | 'HOLD' | null {
21	  if (status === 'in_progress') return 'LIVE'
22	  if (status === 'pending' && (depositCents ?? 0) > 0 && !(depositPaid ?? false)) return 'HOLD'
23	  if (status === 'completed' && depositPaid) return 'PAID'
24	  return null
25	}
26	
27	export function DayChairCard({
28	  booking,
29	  sourceArtistId,
30	  isSelected,
31	  onClick,
32	  onResizeStart,
33	}: DayChairCardProps) {
34	  const { setNodeRef, attributes, listeners, isDragging, transform } = useDraggable({
35	    id: booking.id,
36	    data: { booking, sourceArtistId },
37	  })
38	
39	  // Enter opens the edit sheet (keyboard equivalent of click).
40	  // Space is reserved for dnd-kit's KeyboardSensor drag activation — proxy it through.
41	  const handleKeyDown = (e: React.KeyboardEvent) => {
42	    if (e.key === 'Enter' && onClick) {
43	      e.preventDefault()
44	      onClick(e)
45	      return
46	    }
47	    // Delegate remaining keys (Space, arrows) to dnd-kit's KeyboardSensor listener
48	    if (listeners && typeof listeners.onKeyDown === 'function') {
49	      listeners.onKeyDown(e)
50	    }
51	  }
52	
53	  const startTime = new Date(booking.scheduled_at).toLocaleTimeString('en-US', {
54	    hour: 'numeric',
55	    minute: '2-digit',
56	    hour12: true,
57	  })
58	
59	  const isCancelled = booking.status === 'cancelled'
60	  const statusPill = getStatusPill(booking.status, booking.deposit_cents, booking.deposit_paid)
61	
62	  return (
63	    <div
64	      ref={setNodeRef}
65	      style={{
66	        transform: CSS.Translate.toString(transform),
67	        opacity: isDragging ? 0.5 : 1,
68	      }}
69	      className={cn(
70	        'absolute left-0 right-0 rounded-sm border border-border bg-card p-1.5 overflow-hidden',
71	        'cursor-grab active:cursor-grabbing transition-opacity',
72	        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-rust)]',
73	        isSelected && 'ring-2 ring-rust',
74	        isCancelled && 'opacity-60'
75	      )}
76	      {...attributes}
77	      {...listeners}
78	      onClick={onClick}
79	      onKeyDown={handleKeyDown}
80	      aria-label={`Appointment: ${booking.client.first_name}${booking.client.last_name ? ` ${booking.client.last_name}` : ''} at ${startTime}. Press space to pick up, arrow keys to move, space to drop, or enter to open.`}
81	    >
82	      {/* Service color bar */}
83	      {booking.service?.color && (
84	        <span
85	          className="chair-event-service-bar"
86	          style={{ backgroundColor: booking.service.color }}
87	          aria-hidden="true"
88	        />
89	      )}
90	
91	      <div className="space-y-1">
92	        {/* Client name + time */}
93	        <div className="flex items-center justify-between gap-1">
94	          <span
95	            className={cn(
96	              'text-[11px] font-medium truncate',
97	              isCancelled && 'line-through opacity-60'
98	            )}
99	          >
100	            {booking.client.first_name} {booking.client.last_name ?? ''}
101	          </span>
102	          <span className="text-[10px] tabular-nums shrink-0 opacity-70 whitespace-nowrap">{startTime}</span>
103	        </div>
104	
105	        {/* Service name */}
106	        {booking.service?.name && (
107	          <span className="block text-[10px] opacity-60 truncate">
108	            {booking.service.name}
109	          </span>
110	        )}
111	
112	        {/* Status pill + session meta */}
113	        <div className="flex items-center gap-1">
114	          {statusPill && (
115	            <span className={cn('status-pill-' + statusPill.toLowerCase())}>
116	              {statusPill}
117	            </span>
118	          )}
119	          {booking.session_number != null && (
120	            <span className="font-serif italic text-[8px] opacity-70 ml-auto">
121	              S{booking.session_number}
122	            </span>
123	          )}
124	        </div>
125	
126	        {/* Deposit dot */}
127	        {(booking.deposit_cents ?? 0) > 0 && (
128	          <span
129	            role="img"
130	            title={booking.deposit_paid ? 'Deposit paid' : 'Deposit pending'}
131	            aria-label={booking.deposit_paid ? 'Deposit paid' : 'Deposit pending'}
132	            className={cn('deposit-dot', booking.deposit_paid ? 'paid' : 'unpaid')}
133	          />
134	        )}
135	      </div>
136	
137	      {/* Resize handle */}
138	      <div
139	        className="absolute bottom-0 inset-x-0 h-1.5 cursor-ns-resize hover:bg-rust hover:opacity-30 transition-colors"
140	        onPointerDown={onResizeStart}
141	      />
142	    </div>
143	  )
144	}
